use rk3588_boot_support::Mmio32;use crate::stage14::EntryCpuIo;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum EarlyPinOp{Pull{bank:u8,pin:u8,value:u32},Drive{bank:u8,pin:u8,value:u32},Schmitt{bank:u8,pin:u8,value:u32}}
pub fn apply_early_pin_ops<I:Mmio32>(io:&mut I,base:u64,ops:&[EarlyPinOp])->Result<(),crate::stage12::PinctrlError>{for op in ops{match *op{EarlyPinOp::Pull{bank,pin,value}=>crate::stage12::set_pull_raw(io,base,bank,pin,value)?,EarlyPinOp::Drive{bank,pin,value}=>crate::stage12::set_drive_raw(io,base,bank,pin,value)?,EarlyPinOp::Schmitt{bank,pin,value}=>crate::stage12::set_schmitt_raw(io,base,bank,pin,value)?}}Ok(())}
pub fn apply_entry_and_pins<I:EntryCpuIo,J:Mmio32>(cpu:&mut I,mmio:&mut J,current_el:u64,timer_hz:u64,base:u64,ops:&[EarlyPinOp])->Result<(),crate::stage12::PinctrlError>{crate::stage14::apply_entry_cpu_state(cpu,current_el,timer_hz);apply_early_pin_ops(mmio,base,ops)}
#[cfg(test)]mod tests{use super::*;struct M{n:u8}impl Mmio32 for M{fn read32(&mut self,_:u64)->u32{0}fn write32(&mut self,_:u64,_:u32){self.n+=1}}#[test]fn pins(){let mut m=M{n:0};apply_early_pin_ops(&mut m,0,&[EarlyPinOp::Pull{bank:0,pin:0,value:1},EarlyPinOp::Drive{bank:0,pin:0,value:2}]).unwrap();assert_eq!(m.n,2);}}
